from typing import List

class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        ops = 0
        while True:
            # Check if the array is already non-decreasing
            non_decreasing = True
            for i in range(len(nums) - 1):
                if nums[i] > nums[i + 1]:
                    non_decreasing = False
                    break
            if non_decreasing:
                return ops

            # Find the adjacent pair with the minimum sum (leftmost if tie)
            min_sum = float('inf')
            idx = -1
            for i in range(len(nums) - 1):
                s = nums[i] + nums[i + 1]
                if s < min_sum:
                    min_sum = s
                    idx = i

            # Merge the selected pair
            nums = nums[:idx] + [nums[idx] + nums[idx + 1]] + nums[idx + 2:]
            ops += 1
