class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Generate all substrings (including empty) for both strings
        subs_s = []
        n = len(s)
        for i in range(n + 1):
            for j in range(i, n + 1):
                subs_s.append(s[i:j])

        subs_t = []
        m = len(t)
        for i in range(m + 1):
            for j in range(i, m + 1):
                subs_t.append(t[i:j])

        max_len = 0
        # Check every concatenation S + T
        for S in subs_s:
            lenS = len(S)
            # Small optimisation: skip if even the longest possible T cannot beat current max
            if lenS + m <= max_len:
                continue
            for T in subs_t:
                total_len = lenS + len(T)
                if total_len <= max_len:
                    continue
                cand = S + T
                if cand == cand[::-1]:
                    max_len = total_len
        return max_len
