class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        # prefix_skill[i] = sum of skill[0..i-1]
        prefix_skill = [0] * (n + 1)
        for i in range(1, n + 1):
            prefix_skill[i] = prefix_skill[i - 1] + skill[i - 1]

        free_time = [0] * n  # time each wizard becomes free

        for mana_val in mana:
            # Find the earliest start time for wizard 0
            best = free_time[0]  # i = 0, prefix_skill[0] = 0
            for i in range(1, n):
                cand = free_time[i] - mana_val * prefix_skill[i]
                if cand > best:
                    best = cand
            start_0 = best

            # Update finish times for all wizards after processing this potion
            for i in range(n):
                free_time[i] = start_0 + mana_val * prefix_skill[i + 1]

        return free_time[-1]
