from typing import List
from collections import defaultdict

class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        # Group indices by value
        pos = defaultdict(list)
        for i, x in enumerate(nums):
            pos[x].append(i)

        # res[i] will store the minimum circular distance from i to any other index with the same value
        res = [-1] * n

        for indices in pos.values():
            k = len(indices)
            if k == 1:
                continue  # only one occurrence, distance remains -1
            # indices are already sorted because we traversed nums left to right
            for idx, p in enumerate(indices):
                prev_p = indices[(idx - 1) % k]
                next_p = indices[(idx + 1) % k]

                # distance to previous occurrence (counter-clockwise)
                if prev_p <= p:
                    d1 = p - prev_p
                else:
                    d1 = p + n - prev_p

                # distance to next occurrence (clockwise)
                if next_p >= p:
                    d2 = next_p - p
                else:
                    d2 = next_p + n - p

                res[p] = min(d1, d2)

        return [res[q] for q in queries]
