class Solution:
    def maxSum(self, nums: List[int]) -> int:
        # We can delete any elements, so we can keep exactly one occurrence of each distinct positive number.
        # The selected subarray can then be the whole remaining array (all unique).
        # If there are positive numbers, sum them all (each at most once).
        # Otherwise, we must pick at least one element, so pick the maximum element (<=0).
        distinct_positives = set()
        for num in nums:
            if num > 0:
                distinct_positives.add(num)

        if distinct_positives:
            return sum(distinct_positives)
        else:
            return max(nums)
